    "    const file=fileInput.files[0]; if(uploading || !file) return;\n"
    "    if(!file.name.toLowerCase().endsWith('.bin') || file.size<288) { result.textContent='Chọn file ứng dụng firmware.bin hợp lệ.';return; }\n"
    "    uploading=true; globalThis.classhubOtaUploading=true; button.disabled=true; fileInput.disabled=true;\n"
    "    progress.value=0; result.textContent='Kiểm tra ESP32 trước khi cập nhật…';\n"
    "    resumeCamera=connected() && !paused;\n"
    "    if(resumeCamera) document.getElementById('pause').onclick();\n"
    "    try {\n"
    "      const response=await fetch('/api/device',{cache:'no-store'});\n"
    "      if(!response.ok)throw Error('Không đọc được trạng thái ESP32.');\n"
    "      const state=await response.json();\n"
    "      if(!state.otaMaxBytes)throw Error('Cần nạp bản hỗ trợ OTA và bảng phân vùng qua USB một lần trước.');\n"
    "      if(file.size>state.otaMaxBytes)throw Error('File vượt quá dung lượng vùng OTA.');\n"
    "      if(state.pending || state.otaActive)throw Error('ESP32 đang xử lý yêu cầu khác.');\n"
    "      const xhr=new XMLHttpRequest(); xhr.open('POST','/api/ota'); xhr.timeout=150000;\n"
    "      xhr.setRequestHeader('Content-Type','application/octet-stream'); xhr.setRequestHeader('X-ClassHub-Console','1');\n"
    "      xhr.upload.onprogress=event=>{if(event.lengthComputable){progress.value=event.loaded*100/event.total;result.textContent=progress.value>=100?'Đã gửi file. ESP32 đang kiểm tra và ghi firmware…':`Đang gửi firmware: ${Math.floor(progress.value)}%`;}};\n"
    "      xhr.onload=()=>{\n"
    "        if(xhr.status!==200) {failure('Cập nhật không thành công: '+xhr.responseText);return;}\n"
    "        let data;try{data=JSON.parse(xhr.responseText);}catch{failure('Phản hồi cập nhật không hợp lệ. Kiểm tra ESP32 trước khi thử lại.');return;}\n"
    "        if(!data.ok || !data.rebooting){failure('ESP32 chưa xác nhận cập nhật.');return;}\n"
    "        progress.value=100; result.textContent='Firmware hợp lệ. ESP32 đang khởi động lại; trang sẽ tải lại sau 10 giây. Nếu mất Wi-Fi, kết nối lại mạng của tủ.';\n"
    "        setTimeout(()=>location.reload(),10000);\n"
    "      };\n"
    "      xhr.onerror=()=>failure('Mất kết nối khi cập nhật. Kiểm tra ESP32 trước khi thử lại; không tự gửi lại file.');\n"
    "      xhr.ontimeout=()=>failure('Hết thời gian cập nhật. Kiểm tra ESP32 trước khi thử lại.');\n"
    "      xhr.onabort=()=>failure('Đã ngắt tải firmware.');\n"
    "      xhr.send(file);\n"
    "    } catch(error) { failure(error.message); }\n"
    "  };\n"
    "})();\n"
    "\n"
    "</script></html>";
